{"command": "cat > /app/task_file/output/ko-debug.js << 'EOF'
/**
 * KnockoutJS Template Binding Error Debugger
 * 
 * Helps debug template binding errors by providing enhanced, actionable
 * error messages including the missing property name, available properties,
 * and suggestions for closest matching property names.
 */

/**
 * Calculate the Levenshtein distance between two strings.
 * The Levenshtein distance is a measure of the minimum number of
 * single-character edits (insertions, deletions, or substitutions)
 * required to change one string into the other.
 *
 * @param {string} str1 - The first string
 * @param {string} str2 - The second string
 * @returns {number} The Levenshtein distance
 */
function levenshteinDistance(str1, str2) {
  const m = str1.length;
  const n = str2.length;

  // Create a 2D array to store distances
  const dp = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));

  // Base cases
  for (let i = 0; i <= m; i++) {
    dp[i][0] = i;
  }
  for (let j = 0; j <= n; j++) {
    dp[0][j] = j;
  }

  // Fill in the rest of the table
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (str1[i - 1] === str2[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1];
      } else {
        dp[i][j] = 1 + Math.min(
          dp[i - 1][j],      // deletion
          dp[i][j - 1],      // insertion
          dp[i - 1][j - 1]   // substitution
        );
      }
    }
  }

  return dp[m][n];
}

/**
 * Find the closest matching property name from available properties
 * using Levenshtein distance.
 *
 * @param {string} missingProperty - The property name that was not found
 * @param {string[]} availableProperties - List of available property names
 * @returns {string|null} The closest matching property or null if no close match
 */
function findClosestMatch(missingProperty, availableProperties) {
  let minDistance = Infinity;
  let bestMatch = null;

  for (const prop of availableProperties) {
    const distance = levenshteinDistance(missingProperty, prop);
    if (distance < minDistance) {
      minDistance = distance;
      bestMatch = prop;
    } else if (distance === minDistance && distance <= 3) {
      // Tie-breaker: return the one that comes first alphabetically
      if (prop < bestMatch) {
        bestMatch = prop;
      }
    }
  }

  // Only return a suggestion if within threshold of 3
  if (minDistance <= 3) {
    return bestMatch;
  }

  return null;
}

/**
 * Create a debug helper for KnockoutJS binding errors.
 *
 * @param {Object} viewModel - A KnockoutJS-style ViewModel object
 * @returns {Object} A debug helper object with diagnoseMissingProperty method
 */
function createDebugHelper(viewModel) {
  // Get own property names and sort them alphabetically
  const availableProperties = Object.keys(viewModel).sort();

  return {
    /**
     * Diagnose a missing property binding error.
     *
     * @param {string} propertyName - The name of the property that failed to bind
     * @returns {Object} Diagnostic result object
     */
    diagnoseMissingProperty: function(propertyName) {
      // Check if the property is actually missing
      const isMissing = !viewModel.hasOwnProperty(propertyName);

      if (!isMissing) {
        // Property exists, not an error
        return {
          error: false,
          missingProperty: propertyName,
          availableProperties: availableProperties,
          suggestion: null
        };
      }

      // Find the closest matching property
      const suggestion = findClosestMatch(propertyName, availableProperties);

      return {
        error: true,
        missingProperty: propertyName,
        availableProperties: availableProperties,
        suggestion: suggestion
      };
    }
  };
}

// Export in CommonJS format
module.exports = {
  createDebugHelper: createDebugHelper,
  levenshteinDistance: levenshteinDistance
};
EOF"}

{"command": "cat > /app/task_file/output/test-ko-debug.js << 'EOF'
/**
 * Test script for KnockoutJS Template Binding Error Debugger
 * 
 * Tests the following scenarios:
 * 1. Diagnose missing property "item" (should suggest "items")
 * 2. Diagnose missing property "selctedItem" (should suggest "selectedItem")
 * 3. Diagnose missing property "completelyWrong" (should have null suggestion)
 * 4. Diagnose missing property "isLoad" (should suggest "isLoading")
 */

const { createDebugHelper } = require('./ko-debug.js');

// Define a sample ViewModel with required properties
const sampleViewModel = {
  items: [],
  selectedItem: {},
  filterText: '',
  isLoading: false,
  totalCount: 0
};

// Create a debug helper
const debugHelper = createDebugHelper(sampleViewModel);

// Helper function to run a test
function runTest(testNumber, description, testFn) {
  const result = testFn();
  const passOrFail = result ? 'PASS' : 'FAIL';
  console.log(`${passOrFail} - Test ${testNumber}: ${description}`);
  return result;
}

// Track overall results
let allPassed = true;

// Test 1: Diagnose missing property "item" (should suggest "items")
console.log('\n--- Running Diagnostic Tests ---\n');

allPassed = runTest(1, 
  'Diagnose missing property "item" suggests "items"', 
  () => {
    const result = debugHelper.diagnoseMissingProperty('item');
    const checks = [
      result.error === true,
      result.missingProperty === 'item',
      result.availableProperties.length === 5,
      JSON.stringify(result.availableProperties) === JSON.stringify(['filterText', 'isLoading', 'items', 'selectedItem', 'totalCount']),
      result.suggestion === 'items'
    ];
    console.log('  Result:', {
      error: result.error,
      missingProperty: result.missingProperty,
      availableProperties: result.availableProperties,
      suggestion: result.suggestion
    });
    return checks.every(c => c);
  }
) && allPassed;

// Test 2: Diagnose missing property "selctedItem" (should suggest "selectedItem")
allPassed = runTest(2, 
  'Diagnose missing property "selctedItem" suggests "selectedItem"', 
  () => {
    const result = debugHelper.diagnoseMissingProperty('selctedItem');
    const checks = [
      result.error === true,
      result.missingProperty === 'selctedItem',
      result.suggestion === 'selectedItem'
    ];
    console.log('  Result:', {
      error: result.error,
      missingProperty: result.missingProperty,
      suggestion: result.suggestion
    });
    return checks.every(c => c);
  }
) && allPassed;

// Test 3: Diagnose missing property "completelyWrong" (should have null suggestion)
allPassed = runTest(3, 
  'Diagnose missing property "completelyWrong" returns null suggestion', 
  () => {
    const result = debugHelper.diagnoseMissingProperty('completelyWrong');
    const checks = [
      result.error === true,
      result.suggestion === null
    ];
    console.log('  Result:', {
      error: result.error,
      missingProperty: result.missingProperty,
      suggestion: result.suggestion
    });
    return checks.every(c => c);
  }
) && allPassed;

// Test 4: Diagnose missing property "isLoad" (should suggest "isLoading")
allPassed = runTest(4, 
  'Diagnose missing property "isLoad" suggests "isLoading"', 
  () => {
    const result = debugHelper.diagnoseMissingProperty('isLoad');
    const checks = [
      result.error === true,
      result.missingProperty === 'isLoad',
      result.suggestion === 'isLoading'
    ];
    console.log('  Result:', {
      error: result.error,
      missingProperty: result.missingProperty,
      suggestion: result.suggestion
    });
    return checks.every(c => c);
  }
) && allPassed;

// Summary
console.log('\n--- Summary ---\n');
console.log(allPassed ? 'All tests passed!' : 'Some tests failed!');

// Exit with code 0 if all tests passed, 1 otherwise
process.exit(allPassed ? 0 : 1);
EOF"}

